export function WidgetHeader({
  title = "{{title}}",
  context = "{{context}}",
  toolbar = {{toolbar}},
  color = "{{color}}",
}) {
  return (
    <header style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 10, font: "13px system-ui, sans-serif", color: "#241430", borderBottom: "2px solid " + color, paddingBottom: 8 }}>
      <div>
        <h3 style={{ margin: 0, fontSize: 15 }}>{title}</h3>
        <span style={{ fontSize: 11, opacity: 0.65 }}>{context}</span>
      </div>
      {toolbar && (
        <div style={{ display: "flex", gap: 4, flex: "none" }}>
          <button type="button" aria-label="Refresh" style={{ border: "1px solid #24143022", background: "#FAF7F2", borderRadius: 6, width: 24, height: 24, cursor: "pointer" }}>⟳</button>
          <button type="button" aria-label="Expand" style={{ border: "1px solid #24143022", background: "#FAF7F2", borderRadius: 6, width: 24, height: 24, cursor: "pointer" }}>⤢</button>
        </div>
      )}
    </header>
  );
}
